        $this->assertEqualsWithDelta(100.0, $delta['attendance_delta'], 0.01);
        $this->assertSame('رشد ۱۰۰٫۰', $this->report()->trendLabel($delta['attendance_delta']));
    }

    public function test_a_decline_is_reported_as_a_decline(): void
    {
