    protected $fillable = [
        'user_id',
        'category',
        'title',
        'amount',
        'notes',
        'spent_at',
    ];

    protected function casts(): array
    {
        return [
            'category' => ExpenseCategory::class,
            'amount' => 'integer',
            'spent_at' => 'date',
