        string $title,
        int $amount,
        string $spentAt,
        ?User $by = null,
        ?string $notes = null,
    ): self {
        return static::create([
            'user_id' => $by?->id ?? auth()->id(),
            'category' => $category,
            'title' => $title,
            'amount' => $amount,
            'spent_at' => $spentAt,
            'notes' => $notes,
        ]);
    }

    public function amountLabel(): string
    {
        return to_persian_digits(number_format($this->amount)).' تومان';
    }

